poh.append('          <TabsTrigger value="vessels">Vessels</TabsTrigger>')
poh.append('          <TabsTrigger value="cargo">Cargo</TabsTrigger>')
poh.append('          <TabsTrigger value="insights">Insights</TabsTrigger>')
poh.append('        </TabsList>')
poh.append('        <TabsContent value="dashboard">')
poh.append('          <div className="grid grid-cols-4 gap-4 mb-4">')
poh.append('            <KpiTile label="Active Vessels" value={String(totalVessels)} change={7} icon={Anchor} />')
poh.append('            <KpiTile label="Berth Utilisation" value={avgBerthUtil + "%"} change={3} icon={Activity} />')
poh.append('            <KpiTile label="Total TEU" value={(totalTeu / 1000).toFixed(0) + "K"} change={11} icon={Container} />')
poh.append('            <KpiTile label="Waiting/Anchored" value={String(waitingCount)} change={-15} icon={ShieldAlert} />')
poh.append('          </div>')
poh.append('          <div className="flex gap-6 mb-4 justify-center flex-wrap">')
poh.append('            <HealthRing pct={avgBerthUtil} label="Berth Util" color={TH.ok} />')
poh.append('            <HealthRing pct={89} label="Throughput" color={TH.pri} />')
poh.append('            <HealthRing pct={82} label="On-Time" color={TH.sec} />')
poh.append('            <HealthRing pct={94} label="Safety" color={TH.ok} />')
poh.append('            <HealthRing pct={71} label="Automation" color={TH.ter} />')
poh.append('            <HealthRing pct={88} label="Env Score" color={TH.pri} />')
poh.append('          </div>')
poh.append('          <div className="grid grid-cols-3 gap-4">')
poh.append('            <Card className="poh-chart-card"><CardHeader className="pb-2"><CardTitle className="text-sm font-semibold">Vessel Traffic</CardTitle></CardHeader><CardContent><LineChart data={monthlyData}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="month" tick={{ fontSize: 10 }} /><YAxis tick={{ fontSize: 10 }} /><Tooltip /><Line type="monotone" dataKey="vessels" stroke={TH.pri} strokeWidth={2} /></LineChart></CardContent></Card>')
poh.append('            <Card className="poh-chart-card"><CardHeader className="pb-2"><CardTitle className="text-sm font-semibold">TEU Volume</CardTitle></CardHeader><CardContent><BarChart data={monthlyData}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="month" tick={{ fontSize: 10 }} /><YAxis tick={{ fontSize: 10 }} /><Tooltip /><Bar dataKey="teu" fill={TH.sec} radius={[4, 4, 0, 0]} /></BarChart></CardContent></Card>')
poh.append('            <Card className="poh-chart-card"><CardHeader className="pb-2"><CardTitle className="text-sm font-semibold">Dwell Time Trend</CardTitle></CardHeader><CardContent><AreaChart data={monthlyData}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="month" tick={{ fontSize: 10 }} /><YAxis tick={{ fontSize: 10 }} /><Tooltip /><Area type="monotone" dataKey="dwell" stroke={TH.ter} fill="rgba(5,150,105,0.15)" strokeWidth={2} /></AreaChart></CardContent></Card>')
poh.append('          </div>')
poh.append('        </TabsContent>')
poh.append('        <TabsContent value="vessels">')
poh.append('          <ModuleBreadcrumb items={[{ label: "Port Ops" }, { label: "All Vessels" }]} />')
poh.append('          <SearchFilterToolbar searchQuery={searchQuery} onSearchChange={setSearchQuery} onClearSearch={() => setSearchQuery("")} activeFilters={activeFilters} filterGroups={filterGroups} onToggleFilter={(k, v) => setActiveFilters(p => { const arr = p[k] || []; return arr.includes(v) ? (function(){ const n = {...p}; n[k] = arr.filter(x => x !== v); if(n[k].length === 0) delete n[k]; return n })() : {...p, [k]: [...arr, v]} })} onClearAllFilters={() => setActiveFilters({})} totalItems={totalVessels} filteredCount={filteredVessels.length} onRefresh={() => {}} placeholder="Search by ID, vessel name, or port..." />')
poh.append('          <Card className="poh-table-card"><CardContent className="p-0"><div className="overflow-x-auto"><table className="w-full text-xs"><thead><tr className="border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50"><th className="px-3 py-2 text-left font-semibold">ID</th><th className="px-3 py-2 text-left font-semibold">Vessel</th><th className="px-3 py-2 text-left font-semibold">Status</th><th className="px-3 py-2 text-left font-semibold">Cargo</th><th className="px-3 py-2 text-left font-semibold">Port</th><th className="px-3 py-2 text-left font-semibold">TEU</th><th className="px-3 py-2 text-left font-semibold">Berth Util</th><th className="px-3 py-2 text-left font-semibold">Tonnage</th><th className="px-3 py-2 text-left font-semibold">Dwell</th><th className="px-3 py-2 text-left font-semibold">Op</th></tr></thead><tbody>')
poh.append('            {filteredVessels.slice(0, 30).map((v) => (')
poh.append('              <tr key={v.id} className="poh-table-row border-b border-gray-100 dark:border-gray-800 hover:bg-gray-50 dark:hover:bg-gray-800/30 transition-colors">')
poh.append('                <td className="px-3 py-2 font-mono font-semibold text-sky-600">{v.id}</td>')
poh.append('                <td className="px-3 py-2 text-gray-700 dark:text-gray-300">{v.vesselName}</td>')
