poh.append('                <td className="px-3 py-2 font-semibold">{v.teu.toLocaleString()}</td>')
poh.append('                <td className="px-3 py-2"><UtilBar value={v.berthUtil} /></td>')
poh.append('                <td className="px-3 py-2"><TonnageBar value={v.tonnage} /></td>')
poh.append('                <td className="px-3 py-2 text-gray-600">{v.dwellTime}h</td>')
poh.append('                <td className="px-3 py-2"><OperationBadge op={v.operation} /></td>')
poh.append('              </tr>')
poh.append('            ))}')
poh.append('          </tbody></table></div></CardContent></Card>')
poh.append('        </TabsContent>')
poh.append('        <TabsContent value="cargo">')
poh.append('          <ModuleBreadcrumb items={[{ label: "Port Ops" }, { label: "Cargo Analysis" }]} />')
poh.append('          <div className="grid grid-cols-4 gap-4 mb-4">')
poh.append('            <ValueTile label="FCL Containers" value={String(vessels.filter(v => v.cargoType === "fcl").length)} color={TH.pri} />')
poh.append('            <ValueTile label="Reefer Units" value={String(vessels.filter(v => v.cargoType === "reefer").length)} color={TH.ok} />')
poh.append('            <ValueTile label="Avg Dwell Time" value={Math.round(vessels.reduce((s, v) => s + v.dwellTime, 0) / totalVessels) + "h"} color={TH.sec} />')
poh.append('            <ValueTile label="Crane Moves" value={vessels.reduce((s, v) => s + v.craneMoves, 0).toLocaleString()} color={TH.ter} />')
poh.append('          </div>')
poh.append('          <div className="grid grid-cols-2 gap-4">')
poh.append('            <Card className="poh-chart-card"><CardHeader className="pb-2"><CardTitle className="text-sm font-semibold">Cargo Type Mix</CardTitle></CardHeader><CardContent><PieChart><Pie data={cargoDist} cx="50%" cy="50%" outerRadius={80} dataKey="value" label={({ name, percent }) => name + " " + (percent * 100).toFixed(0) + "%"} labelLine={false}><Cell fill={PC[0]} /><Cell fill={PC[1]} /><Cell fill={PC[2]} /><Cell fill={PC[3]} /><Cell fill={PC[4]} /><Cell fill={PC[5]} /><Cell fill={PC[6]} /><Cell fill={PC[7]} /></Pie><Tooltip /></PieChart></CardContent></Card>')
poh.append('            <Card className="poh-chart-card"><CardHeader className="pb-2"><CardTitle className="text-sm font-semibold">Berth Utilisation Trend</CardTitle></CardHeader><CardContent><BarChart data={monthlyData}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="month" tick={{ fontSize: 10 }} /><YAxis tick={{ fontSize: 10 }} /><Tooltip /><Bar dataKey="berth" fill={TH.pri} radius={[4, 4, 0, 0]} /></BarChart></CardContent></Card>')
poh.append('          </div>')
poh.append('        </TabsContent>')
poh.append('        <TabsContent value="insights">')
poh.append('          <ModuleBreadcrumb items={[{ label: "Port Ops" }, { label: "Insights" }]} />')
poh.append('          <div className="grid grid-cols-2 gap-4">')
poh.append('            <Card className="poh-insight-card border-l-4 border-l-sky-500"><CardContent className="p-4"><div className="flex items-center gap-2 mb-2"><Anchor className="w-4 h-4 text-sky-600" /><span className="font-semibold text-sm">Nhava Sheva Congestion</span></div><p className="text-xs text-gray-600 dark:text-gray-400">JNPT CT-1 berth occupancy at 96% causing 8-hour average wait for arriving vessels. Pre-berthing allocation optimization could reduce dwell time by 20% and save 500 crane moves daily.</p></CardContent></Card>')
poh.append('            <Card className="poh-insight-card border-l-4 border-l-amber-500"><CardContent className="p-4"><div className="flex items-center gap-2 mb-2"><Waves className="w-4 h-4 text-amber-600" /><span className="font-semibold text-sm">Monsoon Impact</span></div><p className="text-xs text-gray-600 dark:text-gray-400">Mumbai port operations expected 15% slowdown during July-August monsoon. Activate Tuticorin V.O.C as overflow hub for container traffic. Ensure reefer power backup across all terminals.</p></CardContent></Card>')
poh.append('            <Card className="poh-insight-card border-l-4 border-l-emerald-500"><CardContent className="p-4"><div className="flex items-center gap-2 mb-2"><CheckCircle2 className="w-4 h-4 text-emerald-600" /><span className="font-semibold text-sm">Vessel Turnaround</span></div><p className="text-xs text-gray-600 dark:text-gray-400">Average vessel turnaround time reduced to 18 hours (down from 26 hours in Q1). Streamlined documentation and dual crane deployment on CT-2 contributed to 30% improvement.</p></CardContent></Card>')
poh.append('            <Card className="poh-insight-card border-l-4 border-l-violet-500"><CardContent className="p-4"><div className="flex items-center gap-2 mb-2"><Ship className="w-4 h-4 text-violet-600" /><span className="font-semibold text-sm">Coastal Shipping Growth</span></div><p className="text-xs text-gray-600 dark:text-gray-400">Coastal cargo volume grew 24% YoY driven by RoRo services between Chennai and Kolkata. Consider adding Ennore Kamarajar terminal for dedicated coastal operations to meet projected demand.</p></CardContent></Card>')
poh.append('          </div>')
poh.append('        </TabsContent>')
poh.append('      </Tabs>')
poh.append('    </div>')
poh.append('  )')
poh.append('}')
